# build-deps.ps1 — build SDL3-uwp and SDL_ttf as WindowsStore DLLs for the UWP port.
#
# Port-owned (D-05). Produces out/uwp-deps/{bin,lib,include} with:
#   SDL3.dll / SDL3.lib, SDL3_ttf.dll / SDL3_ttf.lib, and SDL3/ + SDL3_ttf/ headers.
# The Rust staticlib links against these via the `links` overrides in
# .cargo/uwp-links.toml (generated by gen-links.ps1).
#
# No absolute machine paths: sibling repos are resolved relative to this repo root,
# tools are located with vswhere / PATH. Pass -Sdl3TtfRef to pin the SDL_ttf tag.

[CmdletBinding()]
param(
    # SDL_ttf is not a workspace sibling; clone it. 3.2.x matches sdl3-ttf-sys 0.7.
    [string]$Sdl3TtfRepo = "https://github.com/libsdl-org/SDL_ttf.git",
    [string]$Sdl3TtfRef  = "release-3.2.2",
    [string]$Config      = "Release",
    [switch]$Clean
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

# --- paths (all relative to repo root) --------------------------------------
$repoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path
$sdlSrc   = Join-Path (Split-Path $repoRoot -Parent) "SDL3-uwp"   # ../SDL3-uwp
$out      = Join-Path $repoRoot "out\uwp-deps"
$work     = Join-Path $repoRoot "out\uwp-deps-build"
$ttfSrc   = Join-Path $work "SDL_ttf"

if (-not (Test-Path $sdlSrc)) { throw "SDL3-uwp not found at $sdlSrc (expected sibling ../SDL3-uwp)" }

if ($Clean) {
    foreach ($d in @($out, $work)) { if (Test-Path $d) { Remove-Item -Recurse -Force $d } }
}
New-Item -ItemType Directory -Force -Path $out, $work | Out-Null

# --- toolchain discovery (no hard-coded paths) ------------------------------
$cmake = (Get-Command cmake -ErrorAction Stop).Source
Write-Host "cmake: $cmake"

# WindowsStore (UWP) builds require the Visual Studio generator (Ninja rejects -A/platform
# specs and the WinRT toolchain). Pick the newest installed VS generator dynamically so no
# VS version is hard-coded.
$vsGen = (& $cmake --help | Select-String -Pattern '^\s+(Visual Studio \d+ \d+)' |
    ForEach-Object { $_.Matches[0].Groups[1].Value } | Select-Object -First 1)
if (-not $vsGen) { throw "No Visual Studio CMake generator found (needed for WindowsStore)." }
Write-Host "generator: $vsGen"

# WindowsStore build args shared by SDL3 and SDL_ttf.
$storeArgs = @(
    "-G", $vsGen,
    "-A", "x64",
    "-DCMAKE_SYSTEM_NAME=WindowsStore",
    "-DCMAKE_SYSTEM_VERSION=10.0",
    "-DBUILD_SHARED_LIBS=ON"
)

function Invoke-CMakeBuild([string]$src, [string]$bld, [string[]]$extra) {
    & $cmake -S $src -B $bld @storeArgs @extra
    if ($LASTEXITCODE) { throw "cmake configure failed ($src)" }
    & $cmake --build $bld --config $Config --parallel
    if ($LASTEXITCODE) { throw "cmake build failed ($src)" }
    & $cmake --install $bld --config $Config --prefix $out
    if ($LASTEXITCODE) { throw "cmake install failed ($src)" }
}

# --- SDL3 ---------------------------------------------------------------------
Write-Host "==> Building SDL3-uwp (WindowsStore DLL)"
Invoke-CMakeBuild $sdlSrc (Join-Path $work "SDL3") @(
    "-DSDL_SHARED=ON", "-DSDL_STATIC=OFF", "-DSDL_TESTS=OFF", "-DSDL_EXAMPLES=OFF"
)

# --- SDL_ttf ------------------------------------------------------------------
if (-not (Test-Path $ttfSrc)) {
    Write-Host "==> Cloning SDL_ttf $Sdl3TtfRef"
    git clone --depth 1 --branch $Sdl3TtfRef --recurse-submodules $Sdl3TtfRepo $ttfSrc
    if ($LASTEXITCODE) { throw "git clone SDL_ttf failed" }
}
Write-Host "==> Building SDL_ttf (WindowsStore DLL, against out/uwp-deps SDL3)"
# Build dir MUST differ from the source tree ($ttfSrc) — freetype refuses in-source builds.
Invoke-CMakeBuild $ttfSrc (Join-Path $work "SDL_ttf-build") @(
    "-DSDL3_DIR=$($out -replace '\\','/')/cmake",
    "-DSDLTTF_VENDORED=ON",
    "-DSDLTTF_HARFBUZZ=OFF", "-DSDLTTF_PLUTOSVG=OFF",
    "-DSDLTTF_SAMPLES=OFF"
)

Write-Host ""
Write-Host "Done. Dependencies installed under: $out"
Get-ChildItem -Recurse $out -Include *.dll, *.lib | ForEach-Object { Write-Host "  $($_.FullName.Substring($repoRoot.Length + 1))" }
Write-Host "Next: scripts\uwp\gen-links.ps1 to generate .cargo\uwp-links.toml"
